             ) VALUES (?1, 'queued', 0, 0, 0, NULL, ?2, ?3)
             ON CONFLICT(repo_key) DO UPDATE SET
                status = excluded.status,
                indexed_sessions = 0,
                total_sessions = 0,
                failed_sessions = 0,
